const QuerySkills = yield* Database.resolve('dxn:org.dxos.operation.assistantToolkit.querySkills');
const QueryOps = yield* Database.resolve('dxn:org.dxos.operation.assistantToolkit.queryOperations');
const full = yield* Operation.invoke(QuerySkills, { keys: ['com.example.skill.score'] });
yield* print('SKILL', full);
const opFull = yield* Operation.invoke(QueryOps, { keys: ['dxn:com.example.operation.score'] });
yield* print('OP', opFull);

const Task = yield* Database.resolve('dxn:com.example.type.task:0.1.0');
const open = yield* Database.query(Filter.type(Task, { status: 'open' })).run;
yield* print('open count', open.length);
for (const t of open) yield* print(t.id, t.title, 'priority=', t.priority);
